import{_ as o,c,a0 as a,o as i}from"./chunks/framework.B6JXc2q-.js";const h=JSON.parse('{"title":"系统约束","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/constraints.md","filePath":"architecture/constraints.md"}'),t={name:"architecture/constraints.md"};function r(s,e,d,l,n,u){return i(),c("div",null,e[0]||(e[0]=[a('<h1 id="系统约束" tabindex="-1">系统约束 <a class="header-anchor" href="#系统约束" aria-label="Permalink to &quot;系统约束&quot;">​</a></h1><blockquote><p>状态：现行 适用版本：xiaomusic-core 1.1.x 最后核对：2026-09-28</p></blockquote><p>本文档只保留当前实现中可以由代码、测试或运行装配验证的约束。愿景、尚未实施的设计和历史方案不再作为强制规则。</p><h2 id="_1-约束优先级" tabindex="-1">1. 约束优先级 <a class="header-anchor" href="#_1-约束优先级" aria-label="Permalink to &quot;1. 约束优先级&quot;">​</a></h2><p>发生冲突时按以下顺序裁决：</p><ol><li><code>docs/api/api_v1_spec.md</code>：Public API 契约</li><li><code>docs/spec/*</code>：运行时行为与字段语义</li><li><code>docs/architecture/system_overview.md</code> 与本文件：边界和工程约束</li><li>其他 architecture 文档</li><li><code>ARCHITECTURE.md</code>：入口摘要</li></ol><p>ADR 记录决策历史。只有状态为 Accepted 且未被撤回或取代的 ADR 才能约束当前实现。</p><h2 id="_2-public-api-与路由" tabindex="-1">2. Public API 与路由 <a class="header-anchor" href="#_2-public-api-与路由" aria-label="Permalink to &quot;2. Public API 与路由&quot;">​</a></h2><ul><li>正式外部接口只位于 <code>/api/v1/*</code>，其 OpenAPI 方法与路径集合必须等于白名单。</li><li>Admin 与 Internal Diagnostics 使用独立命名空间；<code>include_in_schema=False</code> 不能替代命名空间隔离或鉴权。</li><li>新增或修改 v1 路由时，必须同步更新 <code>docs/api/api_v1_spec.md</code>、严格请求模型和生产装配测试。</li><li>命令响应只表达动作受理；权威播放状态从 <code>/api/v1/player/state</code> 或 <code>/api/v1/player/stream</code> 读取。</li><li>已弃用路由只有在存在明确兼容窗口及回归测试时才能保留。没有调用方、没有契约价值且已被正式接口取代的路由应删除。</li></ul><p><strong>判断依据</strong>：<code>tests/test_api_boundary_phase1.py</code>、<code>tests/test_removed_device_wrappers.py</code>、<code>xiaomusic/api/routers/__init__.py</code>。</p><h2 id="_3-webui-边界" tabindex="-1">3. WebUI 边界 <a class="header-anchor" href="#_3-webui-边界" aria-label="Permalink to &quot;3. WebUI 边界&quot;">​</a></h2><ul><li>WebUI 只能通过 <code>xiaomusic/webui/src/services/</code> 调用后端，不得依赖 Python runtime、playback 或 device 内部对象。</li><li>正式播放、控制、状态与在线搜索使用 v1 service；Internal API 仅承载仍有实际 WebUI 调用方的内部工具能力。</li><li>前端不得用标题、旧字段或本地推测替代服务端的 track identity、transport state 或在线搜索 <code>play_reference</code>。</li></ul><p><strong>判断依据</strong>：<code>docs/architecture/webui_architecture.md</code>、<code>docs/spec/webui_playback_state_machine_spec.md</code>、WebUI service 与回归测试。</p><h2 id="_4-playback-与状态权威" tabindex="-1">4. Playback 与状态权威 <a class="header-anchor" href="#_4-playback-与状态权威" aria-label="Permalink to &quot;4. Playback 与状态权威&quot;">​</a></h2><ul><li>API 播放与控制必须经 <code>PlaybackFacade</code> 进入 <code>PlaybackCoordinator</code> / transport 链路，router 不直接操纵设备队列。</li><li>播放运行态以 <code>PlaybackRuntimeState</code>、<code>LifecycleToken</code> 和 <code>PlaybackTaskRegistry</code> 为准；Facade 只做投影与边界适配。</li><li>歌单 membership 由 <code>MusicLibrary</code> 管理；设备当前 session 的队列快照和索引由 <code>XiaoMusicDevice</code> 管理。</li><li>state/SSE 查询路径只读，不创建或取消播放任务，不调用 Mina，不隐式修复运行态。</li></ul><p><strong>判断依据</strong>：<code>docs/architecture/state-authority.md</code>、<code>docs/architecture/playback-control-model.md</code>、<code>tests/unit/test_t03h_runtime_snapshot.py</code>、<code>tests/unit/test_t06_playback_task_registry.py</code>。</p><h2 id="_5-source-边界" tabindex="-1">5. Source 边界 <a class="header-anchor" href="#_5-source-边界" aria-label="Permalink to &quot;5. Source 边界&quot;">​</a></h2><ul><li>Source 实现 <code>SourcePlugin.resolve()</code>，只负责把请求解析为 <code>ResolvedMedia</code>；不得直接下发设备命令或修改播放队列。</li><li>内置 source 必须经 <code>register_default_source_plugins()</code> 注册，并在 API <code>source_hint</code> 契约中声明。</li><li>Source 不得持有完整 runtime / <code>XiaoMusic</code> 实例；允许注入完成本 source 职责所需的窄能力，例如 <code>LinkPreparer</code>、引用 store 或 <code>OnlineMusicService</code>。</li><li>MusicFree JS action 属于动态插件协议，不能仅因缺少 Python 静态调用就删除。</li></ul><p><strong>判断依据</strong>：<code>xiaomusic/core/source/</code>、<code>xiaomusic/adapters/sources/default_registry.py</code>、<code>xiaomusic/js_plugin_runner.js</code>、source 测试。</p><h2 id="_6-auth、配置与敏感数据" tabindex="-1">6. Auth、配置与敏感数据 <a class="header-anchor" href="#_6-auth、配置与敏感数据" aria-label="Permalink to &quot;6. Auth、配置与敏感数据&quot;">​</a></h2><ul><li><code>TokenStore</code> / <code>auth.json</code> 是持久认证事实来源；候选 runtime verify 成功后才允许 commit 与 swap。</li><li>不得把 cookie、token、密码、原始插件 item 或媒体敏感 URL 放进 Public API、日志、测试夹具或版本库。</li><li>API 和插件错误对外必须结构化并脱敏；内部日志也应通过既有 redaction 边界。</li></ul><p><strong>判断依据</strong>：<code>docs/spec/auth/auth_runtime_recovery.md</code>、<code>xiaomusic/security/token_store.py</code>、<code>xiaomusic/security/redaction.py</code> 及安全测试。</p><h2 id="_7-异步任务与生命周期" tabindex="-1">7. 异步任务与生命周期 <a class="header-anchor" href="#_7-异步任务与生命周期" aria-label="Permalink to &quot;7. 异步任务与生命周期&quot;">​</a></h2><ul><li>后台任务必须由创建它的组件保存引用、登记到既有 task registry，或由应用 lifespan 持有，并在对应关闭/失效边界取消。</li><li>不使用扫描 <code>asyncio.all_tasks()</code> 加自定义 <code>_owner</code> 属性的全局清理模式。</li><li>播放相关任务名称和所有权必须通过 <code>PlaybackTaskRegistry</code> 保持唯一；旧 session 的回调不得覆盖新 session 状态。</li></ul><p><strong>判断依据</strong>：<code>xiaomusic/playback/task_registry.py</code>、<code>xiaomusic/api/app.py</code>、<code>tests/unit/test_t06_playback_task_registry.py</code>。</p><h2 id="_8-异常与临时兼容" tabindex="-1">8. 异常与临时兼容 <a class="header-anchor" href="#_8-异常与临时兼容" aria-label="Permalink to &quot;8. 异常与临时兼容&quot;">​</a></h2><ul><li>禁止无日志、无返回语义的 <code>except: pass</code>。</li><li>临时兼容必须写清原因、退出条件和保护测试；无需使用固定人名或虚构版本日期充当 owner。</li><li>兼容代码不得成为新功能入口。删除前需检查生产注册、动态分派、现行测试和发布兼容窗口。</li></ul><h2 id="_9-已撤销的旧规则" tabindex="-1">9. 已撤销的旧规则 <a class="header-anchor" href="#_9-已撤销的旧规则" aria-label="Permalink to &quot;9. 已撤销的旧规则&quot;">​</a></h2><p>以下内容曾出现在旧版架构文档中，但与当前实现不符，不再生效：</p><ul><li>“所有状态变化必须通过统一事件模型通知”。当前 EventBus 只承载三个既有通知事件，状态权威仍由各所属模块维护。</li><li>约二十种标准事件、事件 replay、<code>play_id</code> / SSE <code>session_id</code> 和 <code>/api/v1/debug/snapshot</code>。这些设计未落地。</li><li>“所有 asyncio task 通过 <code>_owner</code> 属性由全局 shutdown 扫描取消”。当前采用 lifespan、模块字段和 <code>PlaybackTaskRegistry</code> 的局部 ownership。</li><li>“某些核心文件绝对不能修改”。高风险区域需要更多证据和测试，但不以文件名建立永久禁改名单。</li><li>“CI 已有通用架构静态检查”。现行门禁以具体测试和 workflow 为准，不宣称不存在的检查。</li></ul>',30)]))}const _=o(t,[["render",r]]);export{h as __pageData,_ as default};
